const actions: { id: CampaignActionType; title: string; hint: string }[] = [
  { id: "door-knocking", title: "Recorrer el distrito", hint: "Contacto directo con votantes" },
  { id: "rally", title: "Organizar un mitin", hint: "Visibilidad y movilización" },
  { id: "media-interview", title: "Dar una entrevista", hint: "Instala tus prioridades" },
  { id: "primary-outreach", title: "Hablar con el partido", hint: "Asegura apoyo interno" },
  { id: "fundraising", title: "Recaudar fondos", hint: "Amplía el presupuesto" },
  { id: "make-promise", title: "Hacer una promesa", hint: "Compromiso que se cobrará en el mandato" },
];
function campaignActionCopy(action: CampaignActionType, officeId: string, country: CountryDefinition) {
  const ministerial = officeId === country.ministerialAppointment.officeId;
  const leadership = officeId === country.partyLeadership.officeId;
  const copy: Partial<Record<CampaignActionType, { title: string; hint: string }>> = ministerial ? {
    "door-knocking": { title: "Demostrar resultados", hint: "Presenta tu trayectoria de gestión al equipo ejecutivo" },
    rally: { title: "Defender la cartera", hint: "Explica por qué tu plan merece respaldo" },
    "media-interview": { title: "Responder a la prensa", hint: "Aclara tu experiencia y prioridades" },
    "primary-outreach": { title: "Presentar agenda al ejecutivo", hint: "Busca apoyo directo para el nombramiento" },
    fundraising: { title: "Recaudar fondos", hint: "Amplía los recursos para futuras campañas" },
  } : leadership ? {
    "door-knocking": { title: "Visitar comités del partido", hint: "Escucha a las facciones y sus bases" },
    rally: { title: "Convocar a la militancia", hint: "Moviliza apoyo para la votación interna" },
    "media-interview": { title: "Explicar la plataforma", hint: "Define tu línea ante la prensa" },
    "primary-outreach": { title: "Negociar con las facciones", hint: "Construye respaldo en la bancada" },
    fundraising: { title: "Recaudar fondos", hint: "Amplía los recursos para futuras campañas" },
  } : {};
  return copy[action] ?? actions.find((entry) => entry.id === action)!;
}
const errorMessage = (error: unknown) => error instanceof Error ? error.message : "Ocurrió un error inesperado.";

async function loadCountryDefinition(id: string): Promise<CountryDefinition> {
  const actor = id.startsWith("generated-") ? worldActorDefinitions.find((entry) => `generated-${entry.id}` === id) : undefined;
  if (id.startsWith("generated-") && !actor) throw new Error("El país del guardado no está disponible.");
  const response = await fetch(`/data/countries/${actor ? "peru" : id}.json`);
  if (!response.ok) throw new Error("El país del guardado no está disponible.");
  const base = countrySchema.parse(await response.json()) as CountryDefinition;
  if (!actor && base.id !== id) throw new Error("El país del guardado no coincide con su perfil.");
  return actor ? generateExperimentalCountry(actor, base) : base;
}
const origins: { id: SocialOriginId; label: string }[] = [{id:"urban-working",label:"Origen trabajador urbano"},{id:"rural-working",label:"Origen trabajador rural"},{id:"professional-middle",label:"Clase media profesional"},{id:"business-family",label:"Familia empresarial"},{id:"political-family",label:"Familia política"},{id:"military-family",label:"Familia militar"}];
const professions: { id: ProfessionId; label: string }[] = [{id:"lawyer",label:"Abogado/a"},{id:"doctor",label:"Médico/a"},{id:"teacher",label:"Docente"},{id:"union-organizer",label:"Dirigente sindical"},{id:"business-owner",label:"Empresario/a"},{id:"journalist",label:"Periodista"},{id:"military-officer",label:"Militar"},{id:"activist",label:"Activista"},{id:"economist",label:"Economista"},{id:"athlete",label:"Deportista"},{id:"civil-servant",label:"Funcionario/a"},{id:"academic",label:"Académico/a"}];
const educations: { id: EducationId; label: string }[] = [{id:"none",label:"Sin estudios formales"},{id:"technical",label:"Formación técnica"},{id:"public-university",label:"Universidad pública"},{id:"private-university",label:"Universidad privada"},{id:"abroad",label:"Estudios en el extranjero"}];
const traitOptions = [{id:"natural-orator",label:"Orador nato"},{id:"technocrat",label:"Tecnócrata"},{id:"incorruptible",label:"Incorruptible"},{id:"cunning",label:"Maquiavélico"},{id:"loyal",label:"Leal"},{id:"resentful",label:"Rencoroso"},{id:"populist",label:"Populista"},{id:"survivor",label:"Superviviente"}];
const attributeLabels: Record<AttributeId,string> = {charisma:"Carisma",oratory:"Oratoria",cunning:"Astucia",management:"Gestión",integrity:"Integridad",network:"Red de contactos",health:"Salud"};

export function App() {
  const audio = useGameAudio();
  const [ceremony, setCeremony] = useState<TurnTransition | null>(null);
  const [country, setCountry] = useState<CountryDefinition | null>(null);
  const [countryOptions, setCountryOptions] = useState<readonly { id: string; name: string }[]>([]);
  const [state, setState] = useState<CareerGameState | null>(null);
  const [busy, setBusy] = useState(true);
  const [advancing, setAdvancing] = useState(false);
  const [fastPace, setFastPace] = useState(false);
  const advanceLock = useRef(false);
  const careerWorker = useRef<Worker | null>(null);
  const [message, setMessage] = useState("");
  const [name, setName] = useState("");
  const [age, setAge] = useState(30);
  const [officeId, setOfficeId] = useState("deputy");
  const [districtId, setDistrictId] = useState("");
  const [partyId, setPartyId] = useState("");
  const [partySwitchTarget, setPartySwitchTarget] = useState("");
  const [foundPartyName, setFoundPartyName] = useState("");
  const [seed, setSeed] = useState<string>(crypto.randomUUID());
  const [realism, setRealism] = useState<RealismMode>("realistic");
  const [hallOpen, setHallOpen] = useState(false);
  const [scenario, setScenario] = useState<"constitutional" | "hegemony">("constitutional");
  const [ironman, setIronman] = useState(false);
  const [wizardStep, setWizardStep] = useState(1);
  const [originId, setOriginId] = useState<SocialOriginId>("professional-middle");
  const [professionId, setProfessionId] = useState<ProfessionId>("teacher");
  const [educationId, setEducationId] = useState<EducationId>("public-university");
  const [ideology, setIdeology] = useState<Ideology>({economy:50,social:50,nationalism:50,institutionalism:55,rigidity:35});
  const [traits, setTraits] = useState<string[]>(["natural-orator","technocrat"]);
  const [attributes, setAttributes] = useState<Record<AttributeId,number>>({charisma:10,oratory:10,cunning:10,management:10,integrity:10,network:10,health:10});
  const [tab, setTab] = useState<GameTab>("desk");
  useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[tab]);
  const [personalizing, setPersonalizing] = useState(false);
  const [careerDetails, setCareerDetails] = useState(false);
  const [toolsOpen, setToolsOpen] = useState(false);
  const [officeCampaignRequest, setOfficeCampaignRequest] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(() => localStorage.getItem("mandato.reduce-motion") === "true" || matchMedia("(prefers-reduced-motion: reduce)").matches);
  useEffect(() => { document.documentElement.dataset.reduceMotion = String(reducedMotion); localStorage.setItem("mandato.reduce-motion", String(reducedMotion)); }, [reducedMotion]);
  const [memberQuery, setMemberQuery] = useState("");
  const previewParties = useMemo(() => country ? createGameState(country, seed).parties : [], [country, seed]);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("mandato.text-size.v1");
      document.documentElement.dataset.textSize = saved === "large" || saved === "largest" ? saved : "normal";
    } catch { document.documentElement.dataset.textSize = "normal"; }
  }, []);

  useEffect(() => {
    Promise.all([fetch("/data/countries/index.json").then((response) => response.json()), loadCareer().catch((error) => { setMessage(`El guardado local no se pudo abrir: ${errorMessage(error)}. Puedes importar una copia o iniciar una nueva carrera.`); return null; })])
      .then(async ([manifest, saved]) => {
        const available = (manifest as { countries: { id: string; name: string; file: string }[] }).countries;
        setCountryOptions([...available.map(({ id, name }) => ({ id, name })), ...worldActorDefinitions.map((actor) => ({ id: `generated-${actor.id}`, name: `${worldName(actor.id,actor.name)} · generado ficticio` }))]);
        const selectedId = new URLSearchParams(window.location.search).get("country") ?? saved?.countryId ?? "peru";
        const selected = available.find((entry) => entry.id === selectedId) ?? available[0];
        if (!selected) throw new Error("El catálogo no contiene países disponibles.");
        const generated = selectedId.startsWith("generated-") ? worldActorDefinitions.find((actor) => `generated-${actor.id}` === selectedId) : null;
        const raw = await fetch(`/data/countries/${generated ? "peru.json" : selected.file}`).then((response) => response.json());
        const base = countrySchema.parse(raw) as CountryDefinition;
        const loaded = generated ? generateExperimentalCountry(generated, base) : base;
        const matchingSave = saved?.countryId === loaded.id ? saved : null;
        setCountry(loaded); setDistrictId(loaded.electoralDistricts.find((district) => (district.seatsByChamber[loaded.politicalSystem.legislature.lowerChamber.id] ?? 0) > 0)?.id ?? ""); setPartyId(matchingSave?.playerPartyId ?? ""); setOfficeId(matchingSave?.campaign.officeId ?? (loaded.candidateEligibility.some((candidate) => candidate.officeId === "deputy") ? "deputy" : loaded.candidateEligibility[0]?.officeId ?? "deputy"));
        if (saved?.countryId === loaded.id) setState(saved);
      })
      .catch((error) => setMessage(`No se pudo cargar el escenario: ${errorMessage(error)}`))
      .finally(() => setBusy(false));
  }, []);

  useEffect(() => { if (state) void saveCareer(state).catch((error) => setMessage(`No se pudo guardar: ${errorMessage(error)}`)); }, [state]);
  useEffect(() => () => { careerWorker.current?.terminate(); }, []);

  const party = useMemo(() => state?.world.parties.find((candidate) => candidate.id === state.playerPartyId), [state]);
  const legislatorCount = state?.world.legislators.filter((person) => person.chamberId === state.legislature?.chamberId).length ?? 0;
  const latestBudgetVote = state?.budget.voteHistory.at(-1);
  const visibleMembers = state?.world.legislators.filter((member) => (!state.legislature || member.chamberId === state.legislature.chamberId) && `${member.name} ${member.id} ${state.world.parties.find((candidate)=>candidate.id===member.partyId)?.name ?? ""}`.toLocaleLowerCase().includes(memberQuery.toLocaleLowerCase())).slice(0, 30) ?? [];


  function run(operation: () => CareerGameState) {
    if (advanceLock.current) return null;
    try { const next = operation(); setState(next); setMessage(""); return next; }
    catch (error) { setMessage(errorMessage(error)); return null; }
  }

  function startCareer(quickStart = false) {
    if (!country) return;
    const minimumAge = country.candidateEligibility.find((candidate) => candidate.officeId === officeId)?.minimumAge ?? 18;
    setTab("desk");
    run(() => createCareerGame(country, { seed, name: quickStart && name.trim().length < 2 ? "Alex Ríos" : name,
      age: quickStart ? Math.max(age, minimumAge) : age, originId, professionId, educationId, ideology,
      traitIds: traits, attributes, districtId, officeId, realism, ironman, scenario, ...(partyId ? { partyId } : {}) }));
  }

  async function restoreImportedCareer(file: File) {
    if (advanceLock.current || state?.ironman) return;
    advanceLock.current = true;
    setAdvancing(true);
    setMessage("");
    try {
      const next = await importCareer(file);
      const definition = await loadCountryDefinition(next.countryId);
      careerWorker.current?.terminate(); careerWorker.current = null;
      setCountry(definition); setState(next); setOfficeId(next.campaign.officeId);
      setDistrictId(next.campaign.districtId); setPartyId(next.playerPartyId);
      setTab("desk"); setCareerDetails(false); setPersonalizing(false);
      setOfficeCampaignRequest(0); setToolsOpen(false); setMessage("Partida importada.");
      const url = new URL(window.location.href); url.searchParams.set("country", next.countryId); history.replaceState(null, "", url);
    } catch (error) { setToolsOpen(false); setMessage(`No se pudo importar: ${errorMessage(error)}`); }
    finally { advanceLock.current = false; setAdvancing(false); }
  }

  function handleHudAdvance() {
    if (state?.stage === "election-result") { if (tab === 'career' && !careerDetails) advanceTurn(); else { setCareerDetails(false); setTab("career"); } return; }
    if (state?.stage === 'legacy' || state?.stage === 'term-summary') { setCareerDetails(false); setTab('career'); return; }
    if (state?.stage === "campaign" && (!state.campaign.nominated || state.campaign.actionsRemaining > 0)) {
      setTab("desk"); setOfficeCampaignRequest((value) => value + 1); return;
    }
    advanceTurn();
  }

  async function chooseCountry(id: string) {
    if (state || !country) return;
    try {
      const actor = id.startsWith("generated-") ? worldActorDefinitions.find((entry) => `generated-${entry.id}` === id) : undefined;
      const raw = await fetch(`/data/countries/${actor ? "peru" : id}.json`).then((response) => { if (!response.ok) throw new Error("Este escenario no está disponible."); return response.json(); });
      const base = countrySchema.parse(raw) as CountryDefinition;
      const next = actor ? generateExperimentalCountry(actor,base) : base;
      setCountry(next);
      const office = next.candidateEligibility.some((entry) => entry.officeId === "deputy") ? "deputy" : next.candidateEligibility[0]?.officeId ?? "deputy";
      chooseOffice(office,next); setPartyId("");
      const url = new URL(window.location.href); url.searchParams.set("country",id); history.replaceState(null,"",url);
    } catch (error) { setMessage(errorMessage(error)); }
  }
  function chooseOffice(id: string, definition = country) {
    if (!definition) return; setOfficeId(id);
    const chamber = definition.candidateEligibility.find((entry) => entry.officeId === id)?.chamberId ?? definition.politicalSystem.legislature.lowerChamber.id;
    setDistrictId(definition.electoralDistricts.find((entry) => (entry.seatsByChamber[chamber] ?? 0) > 0)?.id ?? "");
  }
  function advanceTurn() {
    if (!state || !country || advanceLock.current) return;
    if (!["legislature", "executive", "minister", "party-leadership"].includes(state.stage)) {
      const next = run(() => advanceCareer(state, country));
      if (next?.stage === 'election-result') setCeremony({ before: state, after: next });
      return;
    }
    advanceLock.current = true;
    setAdvancing(true);
    const finish = () => { advanceLock.current = false; setAdvancing(false); };
    const fallback = () => {
      careerWorker.current?.terminate(); careerWorker.current = null;
      finish();
      if (fastPace) {
        try { const result = advanceCareerUntilDecision(state, country); setState(result.state); setCeremony({ before: state, after: result.state }); setMessage(result.reason); }
        catch (error) { setMessage(errorMessage(error)); }
      } else { const next = run(() => advanceCareer(state, country)); if (next) setCeremony({ before: state, after: next }); }
    };
    try {
      const worker = careerWorker.current ?? new Worker(new URL("../worker/simulation-worker.ts", import.meta.url), { type: "module" });
      careerWorker.current = worker;
      worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
        finish();
        if (event.data.type === "career-advanced") { setState(event.data.state); setCeremony({ before: state, after: event.data.state }); setMessage(event.data.notice ?? ""); }
        else if (event.data.type === "error") setMessage(event.data.message);
      };
      worker.onerror = fallback;
      const request: WorkerRequest = { type: "career-advance", state, country, untilDecision: fastPace };
      worker.postMessage(request);
    } catch { fallback(); }
  }

  function adjustAttribute(attribute: AttributeId, raw: number) {
    const target = Math.max(1, Math.min(20, raw));
    const difference = target - attributes[attribute];
    const others = (Object.keys(attributes) as AttributeId[]).filter((key) => key !== attribute);
    const next = { ...attributes, [attribute]: target };
    let remaining = Math.abs(difference);
    for (const key of others) {
      if (!remaining) break;
      const capacity = difference > 0 ? next[key] - 1 : 20 - next[key];
      const change = Math.min(remaining, capacity);
      next[key] += difference > 0 ? -change : change;
      remaining -= change;
    }
    if (remaining) setMessage("No quedan puntos disponibles en los demás atributos.");
    else { setAttributes(next); setMessage(""); }
  }

  if (busy) return <main className="loading">Preparando el escenario…</main>;
  if (!country) return <main className="loading">{message || "No hay un escenario disponible."}</main>;

  if (window.location.pathname === "/ui-kit") return <UIKit country={country} state={state ?? createCareerGame(country,{seed:"ui-kit",name:"Alex Molina",age:40,originId,professionId,educationId,ideology,traitIds:traits,attributes,districtId,officeId,realism,ironman:false,scenario})}/>;
  return <><span className="turn-status" role="status">{advancing ? "Procesando trimestre…" : ""}</span><main className={`app-shell ${state && tab === 'desk' ? 'app-shell--cinematic' : 'app-shell--scene'} scene-${tab} ${personalizing && !state ? 'scene-biography' : ''}`} data-scene={tab} aria-busy={advancing} inert={advancing}>
    <GameHud view={tab} cinematic={!!state && tab === 'desk'} state={state} country={country} navigate={(next) => { setCareerDetails(false); setTab(next); }} advance={handleHudAdvance} disabled={advancing} tools={() => setToolsOpen(true)}/>

    <section className="main-column">
      {message && <div className={`alert ${message === "Partida importada." ? "alert-success" : ""}`} role={message === "Partida importada." ? "status" : "alert"}>{message}<button aria-label="Cerrar aviso" onClick={() => setMessage("")}>×</button></div>}
      {state && tab === "desk" ? <DeskScene state={state} country={country} navigate={setTab} campaignRequest={officeCampaignRequest} onCampaignOpened={() => setOfficeCampaignRequest(0)} campaign={(id) => run(() => performCampaignAction(state,id))} resolve={(itemId, optionId) => run(() => resolveInboxOption(state,itemId,optionId))} nominate={() => run(() => nominate(state))}/>  : state && tab === 'career' && !careerDetails ? <div className="game-view"><Button variant="quiet" onClick={() => setTab('desk')}>← Volver al despacho</Button><CareerScene state={state} country={country} action={(id) => run(() => performCampaignAction(state,id))} nominate={() => run(() => nominate(state))} advance={advanceTurn} dossier={() => setCareerDetails(true)} inbox={() => setTab('inbox')} congress={() => setTab('people')} run={run} economy={() => setTab('economy')} world={() => setTab('world')}/></div> : !state && personalizing && tab !== "help" ? <Biography country={country} officeId={officeId} districtId={districtId} cancel={() => setPersonalizing(false)} submit={(input) => run(() => createCareerGame(country, input))}/> : !state && !personalizing && tab !== "help" ? <StartScene country={country} countries={countryOptions} officeId={officeId} chooseCountry={(id) => void chooseCountry(id)} chooseOffice={chooseOffice} quickStart={() => startCareer(true)} personalize={() => setPersonalizing(true)}/> : <SceneDossier open={!!state && tab === "career" && careerDetails} close={() => setCareerDetails(false)}><div className={`game-view game-view--${tab}`}>
      {!state && tab === "help" ? <Suspense fallback={<p role="status">Cargando ayuda…</p>}><HelpView/></Suspense> : !state ? <section className="welcome-grid"><div className="welcome-copy"><span className="eyebrow">LA POLÍTICA SE HACE EN PERSONA</span><h2>Tu nombre aún<br/>no está en la lista.</h2><p>Construye apoyo desde tu distrito, consigue una candidatura y gana un escaño. Los partidos y representantes se generan para esta partida; las instituciones corresponden al país.</p><Button variant="secondary" onClick={() => setPersonalizing(false)}>Volver al mapa y los cargos</Button><div className="country-inline"><strong>{country.name}</strong><span>{country.politicalSystem.formOfGovernment} · {country.politicalSystem.legislature.type === "bicameral" ? `${country.politicalSystem.legislature.lowerChamber.seats} + ${country.politicalSystem.legislature.upperChamber.seats} escaños` : `${country.politicalSystem.legislature.lowerChamber.seats} escaños`}</span></div>{country.experimental && <p className="country-note"><strong>Perfil experimental.</strong> {country.id.startsWith("generated-") ? "Sus instituciones, reglas electorales y sociedad son una plantilla ficticia, no las de este país. " : ""} Las personas, partidos, preferencias sociales y varias agregaciones institucionales son ficticios. Consulta las fuentes y límites del país antes de interpretar sus cifras.</p>}</div>
        <label>Variante de escenario<Selector aria-label="Variante de escenario" value={scenario} onChange={(event) => setScenario(event.target.value as "constitutional" | "hegemony")}><option value="constitutional">Perfil constitucional del país</option><option value="hegemony">Coalición hegemónica ficticia</option></Selector></label>{scenario === "hegemony" && <p className="source-note">Variante ficticia independiente del régimen real del país. La coalición de élites decide el acceso al ejecutivo; el poder puede perderse por purga, golpe o revuelta.</p>}
        <form className="creation-card wizard-card" onSubmit={(event) => { event.preventDefault(); if (wizardStep < 6) { setWizardStep(wizardStep + 1); return; } startCareer(); }}>
          {wizardStep===1&&<div className="quick-start"><button type="button" className="primary-button wide" onClick={()=>startCareer(true)}>Jugar ahora <span>↗</span></button><p>Entra con un personaje listo para jugar. Puedes elegir país y cargo, o personalizarlo con los pasos de abajo.</p></div>}
          <span className="eyebrow">CREA TU PERSONAJE · PASO {wizardStep} DE 6</span><div className="wizard-progress" aria-label={`Paso ${wizardStep} de 6`}>{Array.from({length:6},(_,index)=><i key={index} className={index<wizardStep?"done":""}/>)}</div>
          {wizardStep===1&&<><h3>Tu origen</h3><label>Nombre público<input required minLength={2} maxLength={64} value={name} onChange={(event) => setName(event.target.value)} placeholder="¿Cómo te llamas?"/></label><label>Origen social<Selector value={originId} onChange={(event)=>setOriginId(event.target.value as SocialOriginId)}>{origins.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</Selector></label><label>Cargo inicial<Selector value={officeId} onChange={(event)=>{const nextOffice=event.target.value;setOfficeId(nextOffice);const chamber=country.candidateEligibility.find((candidate)=>candidate.officeId===nextOffice)?.chamberId??country.politicalSystem.legislature.lowerChamber.id;setDistrictId(country.electoralDistricts.find((item)=>(item.seatsByChamber[chamber]??0)>0)?.id??"");}}>{country.candidateEligibility.map((candidate)=><option key={candidate.officeId} value={candidate.officeId}>{officeLabel(country,candidate.officeId)}</option>)}</Selector></label>{officeId!==country.politicalSystem.executive.officeId&&<label>Circunscripción<Selector value={districtId} onChange={(event) => setDistrictId(event.target.value)}>{country.electoralDistricts.filter((district)=>(district.seatsByChamber[country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.chamberId??country.politicalSystem.legislature.lowerChamber.id]??0)>0).map((district) => <option key={district.id} value={district.id}>{district.name}</option>)}</Selector></label>}<label>Semilla de la partida<input value={seed} onChange={(event)=>setSeed(event.target.value)} maxLength={64}/></label><label>Nivel de realismo<Selector value={realism} onChange={(event)=>setRealism(event.target.value as RealismMode)}><option value="relaxed">Relajado · avisos claros, memoria atenuada</option><option value="realistic">Realista · comportamiento estándar</option><option value="relentless">Implacable · rivales persistentes e información parcial</option></Selector></label><p className="wizard-help">El nivel modifica decisiones e información de los NPC; no entrega ni quita recursos.</p><label><input type="checkbox" checked={ironman} onChange={(event)=>setIronman(event.target.checked)}/> Ironman · un guardado automático, sin importar partidas anteriores</label></>}
          {wizardStep===2&&<><h3>Tu profesión</h3><p className="wizard-help">Tu trayectoria aporta contactos y habilidades iniciales.</p><label>Profesión previa<Selector value={professionId} onChange={(event)=>setProfessionId(event.target.value as ProfessionId)}>{professions.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</Selector></label></>}
          {wizardStep===3&&<><h3>Tu formación</h3><p className="wizard-help">El prestigio y la gestión inicial dependen de tu experiencia educativa.</p><label>Formación<Selector value={educationId} onChange={(event)=>setEducationId(event.target.value as EducationId)}>{educations.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</Selector></label></>}
          {wizardStep===4&&<><h3>Tu ideología</h3><p className="wizard-help">Define posiciones y rigidez. Los ejes influirán en la afinidad y los votos.</p>{(["economy","social","nationalism","institutionalism","rigidity"] as const).map((key)=> <label className="range-label" key={key}><span>{({economy:"Estado fuerte ↔ mercado",social:"Conservadurismo ↔ progresismo",nationalism:"Soberanía ↔ integración",institutionalism:"Autoridad ↔ pluralismo",rigidity:"Pragmatismo ↔ dogmatismo"})[key]} <b>{ideology[key]}</b></span><input type="range" min="0" max="100" value={ideology[key]} onChange={(event)=>setIdeology({...ideology,[key]:Number(event.target.value)})}/></label>)}</>}
          {wizardStep===5&&<><h3>Elige 2 o 3 rasgos</h3><p className="wizard-help">Cada rasgo cambia tus fortalezas iniciales y cómo te leen los demás.</p><div className="trait-grid">{traitOptions.map((trait)=><label key={trait.id} className="trait-option"><input type="checkbox" checked={traits.includes(trait.id)} onChange={(event)=>setTraits(event.target.checked?[...traits,trait.id]:traits.filter((id)=>id!==trait.id))} disabled={!traits.includes(trait.id)&&traits.length>=3}/><span>{trait.label}</span></label>)}</div><small>Elegidos: {traits.length} · selecciona entre dos y tres.</small></>}
          {wizardStep===6&&<><h3>Reparte tus atributos</h3><p className="wizard-help">Pool fijo: 70 puntos. La edad mínima para {officeLabel(country,officeId)} es {country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.minimumAge ?? 18} años.</p><label>Edad<input type="number" min={country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.minimumAge ?? 18} max="100" value={age} onChange={(event)=>setAge(Number(event.target.value))}/></label><label>Partido ficticio<Selector value={partyId} onChange={(event) => setPartyId(event.target.value)}><option value="">Generar al iniciar</option>{previewParties.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</Selector></label><div className="attribute-list">{(Object.keys(attributes) as AttributeId[]).map((key)=><label className="attribute-row" key={key}><span>{attributeLabels[key]}</span><input type="range" min="1" max="20" value={attributes[key]} onChange={(event)=>adjustAttribute(key,Number(event.target.value))}/><b>{attributes[key]}</b></label>)}</div><div className="character-summary"><strong>{name || "Tu personaje"}</strong><span>{origins.find((item)=>item.id===originId)?.label} · {professions.find((item)=>item.id===professionId)?.label} · {educations.find((item)=>item.id===educationId)?.label}</span></div></>}
          <div className="wizard-actions">{wizardStep>1&&<button type="button" className="secondary-button" onClick={()=>setWizardStep(wizardStep-1)}>Atrás</button>}<button className="primary-button" type="submit" disabled={wizardStep===5&&(traits.length<2||traits.length>3)}>{wizardStep===6?"Empezar campaña":"Siguiente paso"} <span>{wizardStep===6?"↗":"→"}</span></button></div><small>Escenario reproducible · semilla {seed.slice(0, 8)}</small>
        </form></section> : <>
        <nav className="scene-nav" aria-label="Cambiar de escena"><Button variant="quiet" onClick={() => setTab("desk")}>← Volver al despacho</Button><Selector aria-label="Ir a otra escena" value={tab} onChange={(event) => setTab(event.target.value as GameTab)}>{(["career", "inbox", "people", "press", "economy", "world", "country", "help"] as const).map((item) => <option key={item} value={item}>{({career:"Agenda",inbox:"Carpeta",people:"Congreso",press:"Prensa",economy:"Economía",world:"Mundo",country:"País",help:"Ayuda"})[item]}</option>)}</Selector></nav>

        {tab === "help" && <Suspense fallback={<p role="status">Cargando ayuda…</p>}><HelpView/></Suspense>}
        {tab === "career" && <><CareerGuide state={state}/><PaceControls state={state} fast={fastPace} disabled={advancing} change={setFastPace}/></>}
        {tab === "career" && state.regime && <RegimeView state={state} update={(next) => run(() => next)}/>}
        {tab === "world" && <Suspense fallback={<p role="status">Cargando mundo…</p>}><WorldView state={state} country={country} update={setState}/></Suspense>}
        {tab === "career" && state.government?.status === "active" && <section className="side-card full-card"><h2>Coalición de gobierno</h2><p>Negociar cuesta 5 de capital y puede ser rechazado por distancia ideológica y disposición del partido. Un acuerdo amplía los apoyos; puede ceder una cartera de tu partido sin reemplazar a socios anteriores.</p><div className="member-actions">{state.world.parties.filter((p) => !state.government!.supportPartyIds.includes(p.id)).map((p) => <button key={p.id} disabled={state.player.resources.politicalCapital < 5 || Boolean(state.government?.challenge)} onClick={() => run(() => negotiateGovernmentSupport(state, p.id, country))}>Negociar gobierno con {p.name}</button>)}</div></section>}
        {tab === "career" && <div className="content-grid"><section className="feature-card"><div className="card-head"><div><span className="eyebrow">{stageLabel(state)}</span><h2>{state.stage === "campaign" ? `Semana ${state.campaign.week} de 4` : state.stage === "legislature" ? `Sesión ${state.legislature?.turn ?? 0} de ${state.legislature?.totalTurns ?? 0}` : state.stage === "executive" ? `Trimestre ${state.government?.termTurn ?? 0} de ${state.government?.totalTermTurns ?? 0}` : state.stage === "election-result" ? "Resultado electoral" : "Resumen de carrera"}</h2></div><span className="seat-icon">{state.stage === "legislature" ? "§" : "◎"}</span></div>
          {state.stage === "campaign" ? <><div className="metric-row"><div><span>{(state.campaign.officeId === country.partyLeadership.officeId || state.campaign.officeId === country.ministerialAppointment.officeId) ? "Impacto de campaña" : "Preferencia"}</span><strong>{state.campaign.playerPreferencePercent.toFixed(1)}%</strong></div><div><span>Acciones esta semana</span><strong>{state.campaign.actionsRemaining}/2</strong></div><div><span>Fondos</span><strong>{state.player.resources.campaignFunds.toFixed(0)}k</strong></div></div><div className="progress-track"><i style={{width:`${Math.min(100,state.campaign.playerPreferencePercent*4)}%`}}/></div><h3>Elige una acción</h3><div className="action-grid">{actions.filter((action)=>(state.campaign.officeId !== country.partyLeadership.officeId && state.campaign.officeId !== country.ministerialAppointment.officeId) || action.id !== "make-promise").map((action) => <button key={action.id} disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds < Math.max(0,campaignActionCost(action.id))} className="action-card" onClick={() => run(() => performCampaignAction(state, action.id))}><strong>{campaignActionCopy(action.id,state.campaign.officeId,country).title}</strong><span>{campaignActionCopy(action.id,state.campaign.officeId,country).hint}</span><span className="action-cost">{action.id==="fundraising"?"Recibes 12k · 1 acción":`${campaignActionCost(action.id)}k · 1 acción`}</span><b>↗</b></button>)}</div>{state.campaign.districtId === "national" && state.campaign.officeId !== country.ministerialAppointment.officeId && <section className="proposal"><span className="eyebrow">CAMPAÑA NACIONAL</span><h3>Agenda, encuestas y debate</h3><p>Agenda actual: {state.world.socialBlocks.find((block)=>block.id===state.campaign.nationalAgenda)?.name ?? "sin definir"}. Preferencia estimada: {state.campaign.playerPreferencePercent.toFixed(1)}%.</p><div className="action-grid">{state.world.socialBlocks.slice(0,4).map((block)=><button key={block.id} className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<0} onClick={()=>run(()=>performCampaignAction(state,"set-national-agenda",block.id))}>Fijar agenda: {block.name}</button>)}<button className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<2} onClick={()=>run(()=>performCampaignAction(state,"publish-poll"))}>Publicar encuesta · 2k</button><button className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<4} onClick={()=>run(()=>performCampaignAction(state,"national-debate"))}>Participar en debate · 4k</button></div>{state.campaign.pollHistory.slice(-2).map((poll,index)=><p key={`poll-${index}`}>Encuesta semana {poll.week}: {poll.explanation}</p>)}{state.campaign.debateHistory.slice(-2).map((debate,index)=><p key={`debate-${index}`}>Debate semana {debate.week}: {debate.explanation}</p>)}</section>}<div className="button-row"><button className="secondary-button" onClick={() => run(() => nominate(state))}>{state.campaign.officeId === country.ministerialAppointment.officeId ? state.campaign.nominated ? "Candidatura confirmada ✓" : "Confirmar candidatura" : state.campaign.officeId === country.partyLeadership.officeId ? state.campaign.nominated ? "Nominación confirmada ✓" : "Confirmar candidatura" : state.campaign.nominated ? "Nominación confirmada ✓" : "Confirmar nominación"}</button><button className="primary-button" onClick={advanceTurn}>Siguiente semana <span>→</span></button></div></> : state.stage === "election-result" ? <><div className="result-banner"><strong>{state.campaign.officeId === country.ministerialAppointment.officeId ? state.electionOutcome?.elected ? "NOMBRAMIENTO MINISTERIAL OBTENIDO" : "NOMBRAMIENTO MINISTERIAL RECHAZADO" : state.campaign.officeId === country.partyLeadership.officeId ? state.electionOutcome?.elected ? "LIDERAZGO PARTIDARIO GANADO" : "LIDERAZGO PARTIDARIO NO OBTENIDO" : state.electionOutcome?.elected ? state.campaign.officeId === country.politicalSystem.executive.officeId ? "CARGO EJECUTIVO GANADO" : "ESCAÑO GANADO" : state.campaign.officeId === country.politicalSystem.executive.officeId ? "SIN CARGO EJECUTIVO" : "SIN ESCAÑO"}</strong><p>{state.electionOutcome?.explanation}</p></div><button className="primary-button wide" onClick={advanceTurn}>{state.electionOutcome?.elected ? state.campaign.officeId === country.ministerialAppointment.officeId ? "Iniciar ministerio" : "Iniciar mandato" : "Ver cierre de carrera"} <span>→</span></button></> : state.stage === "legislature" ? <><div className="proposal"><span className="eyebrow">PROPUESTA EN DEBATE</span><h3>{state.legislature?.currentProposal?.title ?? "Votación cerrada"}</h3><p>{state.legislature?.currentProposal?.description ?? "Avanza al siguiente turno para continuar."}</p></div><div className="metric-row"><div><span>Legisladores</span><strong>{legislatorCount}</strong></div><div><span>Acciones</span><strong>{state.legislature?.actionsRemaining}</strong></div><div><span>Votaciones</span><strong>{state.legislature?.voteHistory.length}</strong></div></div>{country.politicalSystem.executive.selection === "legislative-investiture" && <section className="proposal"><span className="eyebrow">FORMACIÓN DE GOBIERNO</span><h3>{state.government?.status === "active" ? "Gobierno en funciones" : "Investidura parlamentaria"}</h3>{!state.government || state.government.status === "ended" || state.government.status === "removed" ? <button className="secondary-button" onClick={() => run(() => startGovernmentInvestiture(state,country))}>Presentar candidatura a la investidura</button> : state.government.status === "awaiting-investiture" ? <><p>Ronda {state.government.round === "first" ? "inicial: mayoría absoluta" : "posterior: mayoría simple"}. Partidos de apoyo: {state.government.supportPartyIds.length}. Capital político: {state.player.resources.politicalCapital}.</p><div className="button-row">{state.world.parties.filter((candidate)=>!state.government?.supportPartyIds.includes(candidate.id)).slice(0,3).map((candidate)=><button className="secondary-button" key={candidate.id} disabled={state.player.resources.politicalCapital<5} onClick={()=>run(()=>negotiateGovernmentSupport(state,candidate.id,country))}>Negociar con {candidate.name}</button>)}<button className="primary-button" onClick={()=>run(()=>resolveGovernmentInvestiture(state,country))}>Votar investidura</button></div></> : <><p>Apoyo afirmativo en la investidura: {state.government.lastInvestitureYes ?? 0}. Gabinete ficticio de {state.government.cabinet.length} ministros.</p><ul>{state.government.cabinet.map((minister)=><li key={minister.officeId}>{minister.title}: {state.world.legislators.find((member)=>member.id===minister.legislatorId)?.name}</li>)}</ul></>}</section>}{state.government?.status === "active" && <section className="proposal"><span className="eyebrow">PROYECTOS DE GOBIERNO</span><p>Presenta una iniciativa y consulta el voto nominal del Gobierno.</p><div className="button-row"><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"employment"))}>Empleo · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"services"))}>Servicios · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"investment"))}>Inversión · 3 capital</button></div>{[...(state.government.policyVotes ?? [])].slice(-2).reverse().map((vote)=><p key={vote.id}>{vote.title}: {vote.passed ? "aprobado" : "rechazado"} · {vote.explanation}</p>)}</section>}<div className="button-row"><button className="secondary-button" disabled={!state.legislature?.currentProposal || !state.legislature.actionsRemaining} onClick={() => run(() => castVote(state,"no"))}>Votar en contra</button><button className="primary-button" disabled={!state.legislature?.currentProposal || !state.legislature.actionsRemaining} onClick={() => run(() => castVote(state,"yes"))}>Votar a favor <span>→</span></button></div><button className="text-button" onClick={advanceTurn}>Cerrar sesión y avanzar trimestre →</button></> : state.stage === "executive" ? <><div className="result-banner"><strong>MANDATO EN CURSO</strong><p>Tu aprobación es {state.world.approvalPercent.toFixed(1)}%; el gabinete está compuesto por personajes generados.</p></div><h3>Gabinete</h3><ul>{state.government?.cabinet.map((minister)=><li key={minister.officeId}>{minister.title}: {state.world.legislators.find((member)=>member.id===minister.legislatorId)?.name} · lealtad {minister.loyalty}</li>)}</ul><section className="proposal"><span className="eyebrow">INICIATIVAS DEL EJECUTIVO</span><h3>Decretos y proyectos</h3><p>Decretos: acciones ejecutivas con efecto moderado. Proyectos: votación nominal de la cámara; la mayoría de más de 50% es una abstracción del prototipo.</p><div className="action-grid"><button className="secondary-button" disabled={state.player.resources.politicalCapital<4} onClick={()=>run(()=>issueExecutiveDecree(state,"services"))}>Decreto de servicios · 4 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<4} onClick={()=>run(()=>issueExecutiveDecree(state,"investment"))}>Decreto de inversión · 4 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"employment"))}>Proyecto de empleo · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"services"))}>Proyecto de servicios · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"investment"))}>Plan de inversión · 3 capital</button></div>{[...(state.government?.policyVotes ?? [])].slice(-3).reverse().map((vote)=><article key={vote.id}><strong>{vote.title} · {vote.passed ? "aprobado" : "rechazado"}</strong><p>{vote.explanation}</p><details><summary>Ver papeletas</summary>{vote.votes.map((ballot)=><p key={ballot.legislatorId}>{state.world.legislators.find((member)=>member.id===ballot.legislatorId)?.name ?? ballot.legislatorId}: {({yes:'a favor',no:'en contra',abstain:'abstención',absent:'ausente'})[ballot.choice]} — {ballot.reasons.join(" ")}</p>)}</details></article>)}</section><button className="primary-button wide" onClick={advanceTurn}>Avanzar trimestre <span>→</span></button></>  : state.stage === "minister" ? <><div className="result-banner"><strong>MINISTERIO EN FUNCIONES · {country.ministerialAppointment.portfolios.find((portfolio)=>portfolio.id===state.ministry?.portfolioId)?.title.toUpperCase()}</strong><p>Nombramiento de {state.world.legislators.find((member)=>member.id===state.ministry?.authorityId)?.name ?? "un ejecutivo NPC"} · respaldo {state.ministry?.supportPercent.toFixed(1)}% · el cargo dura hasta el término configurado o hasta que caiga el respaldo ejecutivo.</p></div><div className="metric-row"><div><span>Trimestre</span><strong>{state.ministry?.termTurn}/{state.ministry?.totalTermTurns}</strong></div><div><span>Apoyo ejecutivo</span><strong>{state.ministry?.supportPercent.toFixed(1)}%</strong></div><div><span>Acciones disponibles</span><strong>{state.ministry?.actionsRemaining}/2</strong></div></div><h3>Decisiones ministeriales</h3><div className="action-grid"><button className="action-card" disabled={!state.ministry?.actionsRemaining} onClick={()=>run(()=>performMinistryAction(state,country,"deliver-results"))}><strong>Entregar resultados</strong><span>No cuesta capital. Mejora las variables prioritarias de la cartera.</span></button><button className="action-card" disabled={!state.ministry?.actionsRemaining || state.player.resources.politicalCapital<4} onClick={()=>run(()=>performMinistryAction(state,country,"negotiate-resources"))}><strong>Negociar recursos</strong><span>Cuesta 4 de capital y fortalece tu relación con el ejecutivo.</span></button><button className="action-card" disabled={!state.ministry?.actionsRemaining || state.player.resources.politicalCapital<3} onClick={()=>run(()=>performMinistryAction(state,country,"manage-crisis"))}><strong>Gestionar una crisis</strong><span>Cuesta 3 de capital y protege la cartera ante una presión inmediata.</span></button></div><h3>Registro ministerial</h3><ul>{state.ministry?.actionsTaken.slice(-4).map((entry,index)=><li key={`${entry.turn}-${index}`}>Trimestre {entry.turn}: {readableCareerText(entry.explanation,country)}</li>)}</ul><button className="primary-button wide" onClick={advanceTurn}>Avanzar trimestre <span>→</span></button></> : state.stage === "party-leadership" ? <><div className="result-banner"><strong>{state.partyLeadership?.role === "opposition" ? "LIDERAZGO DE OPOSICIÓN EN CURSO" : "LIDERAZGO PARTIDARIO EN CURSO"}</strong><p>{party?.name ?? "Tu partido ficticio"} · {state.partyLeadership?.role === "opposition" ? "tu bancada ejerce control político desde la oposición" : "tu bancada forma parte del bloque de gobierno"} · respaldo {state.partyLeadership?.supportPercent.toFixed(1)}%.</p></div><div className="metric-row"><div><span>Trimestre</span><strong>{state.partyLeadership?.termTurn}/{state.partyLeadership?.totalTermTurns}</strong></div><div><span>Acciones disponibles</span><strong>{state.partyLeadership?.actionsRemaining}/2</strong></div><div><span>Capital político</span><strong>{state.player.resources.politicalCapital.toFixed(0)}</strong></div></div><h3>Decisiones de liderazgo</h3><div className="action-grid"><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<5} onClick={()=>run(()=>performPartyLeadershipAction(state,"unify-factions"))}><strong>Unificar facciones</strong><span>Cuesta 5 de capital. Mejora lealtad y respaldo interno.</span></button><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<3} onClick={()=>run(()=>performPartyLeadershipAction(state,"renew-platform"))}><strong>Renovar la plataforma</strong><span>Cuesta 3 de capital. Sube ligeramente el respaldo público y la cohesión.</span></button><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<4} onClick={()=>run(()=>performPartyLeadershipAction(state,"enforce-discipline"))}><strong>Imponer disciplina</strong><span>Cuesta 4 de capital. Refuerza la disciplina con costos de lealtad y apoyo público.</span></button></div><h3>Decisiones anteriores</h3><ul>{state.partyLeadership?.actionsTaken.slice(-4).map((entry,index)=><li key={`${entry.turn}-${index}`}>Trimestre {entry.turn}: {readableCareerText(entry.explanation,country)}</li>)}</ul><button className="primary-button wide" onClick={advanceTurn}>Avanzar trimestre <span>→</span></button></> : state.stage === "term-summary" ? <><div className="result-banner"><strong>MANDATO CERRADO</strong><p>El historial político, los votos, las promesas y las decisiones de {state.player.name} quedan listos para valorar.</p></div><h3>Continuar la carrera</h3><p>Elige otro cargo permitido por las instituciones del país o cierra tu trayectoria.</p><div className="button-row career-option-grid">{country.ministerialAppointment.portfolios.filter((portfolio)=>canStartMinisterialAppointment(state,country,portfolio.id)).map((portfolio)=><button className="secondary-button" key={portfolio.id} onClick={()=>run(()=>startMinisterialAppointment(state,country,portfolio.id))}>Postular a ministro de {portfolio.title}</button>)}{canStartPartyLeadershipElection(state,country) && <button className="secondary-button" onClick={()=>run(()=>startPartyLeadershipElection(state,country))}>Competir por {party?.name && state.government?.supportPartyIds.includes(state.playerPartyId) ? country.partyLeadership.title.toLowerCase() : "el liderazgo de oposición"}</button>}{country.candidateEligibility.filter((candidate)=>canStartNextCareerCampaign(state,country,candidate.officeId)).map((candidate)=><button className="secondary-button" key={candidate.officeId} onClick={()=>run(()=>startNextCareerCampaign(state,country,candidate.officeId))}>Postular a {officeLabel(country,candidate.officeId)}</button>)}</div><section className="proposal"><span className="eyebrow">AFILIACIÓN Y ORGANIZACIÓN</span><h3>{party?.name ?? "Tu partido"}</h3><p>Cambiar de partido cuesta 4 puntos de capital y deja resentimiento en la bancada anterior. Fundar una organización cuesta 8 puntos de capital y 15 mil de fondos.</p><label>Afiliarte a otro partido<Selector aria-label="Afiliarte a otro partido" value={partySwitchTarget} onChange={(event)=>setPartySwitchTarget(event.target.value)}><option value="">Elegir partido</option>{state.world.parties.filter((candidate)=>candidate.id!==state.playerPartyId).map((candidate)=><option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</Selector></label><button className="secondary-button" disabled={!partySwitchTarget||state.player.resources.politicalCapital<4} onClick={()=>run(()=>changePartyAffiliation(state,partySwitchTarget))}>Cambiar de partido</button><label>Nombre del nuevo partido<input aria-label="Nombre del nuevo partido" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName))}>Fundar partido</button></section><button className="primary-button wide" onClick={() => run(() => retireCareer(state))}>Retirarme y generar mi legado</button></> : <><div className="result-banner"><strong>LEGADO · {state.legacy ? legacyCanon.archetypes[state.legacy.archetype].label.toUpperCase() : ""}</strong><p>{state.legacy?.summary}</p></div><h3>Momentos que definieron la carrera</h3><ul>{state.legacy?.milestones.map((milestone,index)=><li key={index}>{readableCareerText(milestone,country)}</li>)}</ul><div className="metric-row"><div><span>Revisión a 5 años</span><strong>{state.legacy?.reevaluationAt5}</strong></div><div><span>Revisión a 15 años</span><strong>{state.legacy?.reevaluationAt15}</strong></div><div><span>Revisión a 30 años</span><strong>{state.legacy?.reevaluationAt30 ?? "—"}</strong></div><div><span>Estado</span><strong>{state.lifeStatus === "deceased" ? "Fallecido" : "Retirado"}</strong></div></div>{state.lifeStatus === "retired" && <><button onClick={()=>void navigator.clipboard.writeText(state.legacy?.shareText ?? "")}>Copiar tarjeta</button>{state.returnCall.status === "offered" ? <><p>{party?.name ?? "Tu partido ficticio"} te ofrece volver. Aceptar agrega tres puntos de respaldo inicial.</p><button className="primary-button" onClick={() => run(() => returnFromRetirement(state,"deputy",country,"party-call"))}>Aceptar el llamado</button><button className="secondary-button" onClick={() => run(() => declineReturnCall(state))}>Rechazar y seguir retirado</button><label>Nombre del nuevo partido<input aria-label="Nombre del partido para volver" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName,country,"deputy"))}>Fundar partido y volver como agente libre</button></> : <><button className="primary-button wide" onClick={() => run(() => returnFromRetirement(state,"deputy",country,"agent-free"))}>Volver como agente libre</button><label>Nombre del nuevo partido<input aria-label="Nombre del partido para volver" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName,country,"deputy"))}>Fundar partido y volver como agente libre</button></>}<h3>Hacedor de reyes</h3><p>Apoya a una figura ficticia para aumentar su influencia.</p><div className="button-row">{state.world.legislators.slice(0,3).map((successor)=><button className="secondary-button" key={successor.id} onClick={()=>run(()=>backSuccessor(state,successor.id))}>Respaldar a {successor.name}</button>)}</div></>}</>}
        </section>{state.government?.status === "active" && <section className="side-card"><span className="eyebrow">ESTABILIDAD DEL GOBIERNO</span><h3>Riesgo {state.realism === "relentless" ? state.government.fallRiskPercent >= 55 ? "alto" : state.government.fallRiskPercent >= 30 ? "medio" : "bajo" : `${state.government.fallRiskPercent}%`}</h3>{state.government.warningSignals.length ? <ul>{state.government.warningSignals.map((signal)=><li key={signal}>{signal}</li>)}</ul> : <p>Sin señales de alerta. El apoyo y la aprobación sostienen el mandato.</p>}<h3>Reorganizar gabinete</h3>{state.government.cabinet.map((minister)=><details key={minister.officeId}><summary>{minister.title}</summary>{state.world.legislators.filter((member)=>member.chamberId===state.government?.chamberId&&member.id!==minister.legislatorId).slice(0,3).map((member)=><button className="text-button" key={member.id} onClick={()=>run(()=>appointMinister(state,minister.officeId,member.id))}>Nombrar a {member.name} · {member.loyalty} lealtad</button>)}</details>)}{state.government.challenge ? <><p>Procedimiento: {state.government.challenge.type} · fase {state.government.challenge.phase} · día {state.government.challenge.daysElapsed}.{state.government.challenge.successorId ? ` Sucesor propuesto: ${state.world.legislators.find((member)=>member.id===state.government?.challenge?.successorId)?.name ?? "NPC"}.` : ""}</p><div className="button-row">{state.government.challenge.phase === "defense" && <button className="secondary-button" onClick={()=>run(()=>defendGovernment(state))}>Defender al Gobierno</button>}<button className="secondary-button" onClick={()=>run(()=>advanceChallengeDays(state,country,state.government?.challenge?.phase === "admission" ? 3 : 5))}>Avanzar días del procedimiento</button>{state.government.challenge.phase === "defense" && <button className="primary-button" onClick={()=>run(()=>resolveGovernmentChallenge(state,country))}>Resolver votación</button>}</div></> : <button className="secondary-button" onClick={()=>run(()=>submitGovernmentChallenge(state,country))}>Iniciar procedimiento de control</button>}</section>}{(state.government?.status === "active" || state.stage === "legislature") && <section className="side-card"><span className="eyebrow">PRESUPUESTO ANUAL</span><h3>Ejercicio {state.budget.fiscalYear}</h3><p>Ingresos índice {state.budget.revenueIndex.toFixed(1)} · gasto {state.budget.spendingIndex.toFixed(1)} · deuda {state.budget.debtIndex.toFixed(1)}</p><ul><li>Servicios públicos: {state.budget.servicesSharePercent}%</li><li>Inversión: {state.budget.investmentSharePercent}%</li><li>Transferencias: {state.budget.transfersSharePercent}%</li><li>Seguridad: {state.budget.securitySharePercent}%</li></ul><p>{state.budget.lastProposalQuarterIndex > state.budget.lastApprovedQuarterIndex ? "Hay una propuesta anual pendiente en la bandeja." : state.budget.lastDecisionId ? "La última decisión está registrada en el diario." : "Aún no se ha aprobado una decisión anual."}</p>{latestBudgetVote && <details><summary>Actas de votación presupuestaria ({state.budget.voteHistory.length}) · última {latestBudgetVote.passed ? "aprobada" : "rechazada"}</summary>{[...state.budget.voteHistory].reverse().map((vote,index)=><details key={`${vote.turn}-${index}`}><summary>Trimestre {vote.turn} · {vote.passed ? "aprobada" : "rechazada"} · {vote.yes} a favor, {vote.no} en contra</summary><div className="vote-reasons">{vote.votes.map((ballot)=>{const voter=state.world.legislators.find((member)=>member.id===ballot.legislatorId);return <p key={ballot.legislatorId}><strong>{voter?.name ?? ballot.legislatorId} · {({yes:'a favor',no:'en contra',abstain:'abstención',absent:'ausente'})[ballot.choice]}</strong> — {ballot.reasons.join(" ")}</p>})}</div></details>)}</details>}</section>}<aside className="side-stack"><section className="side-card"><span className="eyebrow">DIARIO DE CAMPAÑA</span><h3>Lo que ha pasado</h3><ol className="log-list">{[...state.log].reverse().slice(0,5).map((entry,index)=><li key={`${entry.turn}-${index}`}><span className="log-dot"/><div><strong>{readableCareerText(entry.text,country)}</strong><p>{readableCareerText(entry.explanation,country)}</p></div></li>)}</ol></section><section className="side-card compact"><span className="eyebrow">TU ORGANIZACIÓN</span><h3>{party?.name ?? "Partido de la partida"}</h3><p>Facción ficticia · {state.ministry ? `cartera de ${country.ministerialAppointment.portfolios.find((portfolio)=>portfolio.id===state.ministry?.portfolioId)?.title}` : `lista del distrito de ${country.electoralDistricts.find((district)=>district.id===state.campaign.districtId)?.name ?? "escenario nacional"}`}</p></section></aside></div>}
        {tab === "inbox" && <Suspense fallback={<p>Abriendo la bandeja…</p>}><InboxView state={state} country={country} onResolve={(itemId, optionId) => run(() => resolveInboxOption(state, itemId, optionId))}/></Suspense>}
        {tab === "people" && <CongressScene state={state} negotiate={(id) => run(() => negotiateWithLegislator(state,id))} betray={(id) => run(() => applyBetrayalMemory(state,id,"Rompió públicamente el acuerdo."))} vote={(choice) => run(() => castVote(state,choice))}/>}
        {tab === "press" && <PressScene state={state} country={country}/>}
        {tab === "economy" && state && <Suspense fallback={<p>Cargando economía…</p>}><EconomyView state={state} country={country} run={run}/></Suspense>}        {tab === "country" && <section className="side-card full-card"><span className="eyebrow">DATOS E INSTITUCIONES</span><h2>{country.name}</h2><p>Ficha versionada {country.dataVersion}. El juego utiliza parámetros institucionales y económicos fechados; genera la política de cada partida.</p>{country.politicalSystem.legislature.type === "bicameral" && country.politicalSystem.legislature.upperChamber.appointments && <p className="source-note">La cámara alta representa nombramientos o delegaciones institucionales. El motor agrupa sus puestos para la jugabilidad; no simula cada órgano territorial ni su procedimiento de voto.</p>}<div className="country-facts"><div><span>Gobierno</span><strong>{institutionLabels.governments[country.politicalSystem.formOfGovernment]}</strong></div><div><span>Legislatura</span><strong>{institutionLabels.legislatures[country.politicalSystem.legislature.type]}</strong></div><div><span>Distritos</span><strong>{country.electoralDistricts.length}</strong></div><div><span>Exportaciones de bienes</span><strong>US$ {(country.trade.goodsExportsUsd/1e9).toFixed(1)} mil M · {country.trade.dataYear}</strong></div></div><h3>Instituciones del país</h3><ul>{(country.politicalSystem.legislature.type === "bicameral" ? [country.politicalSystem.legislature.lowerChamber,country.politicalSystem.legislature.upperChamber] : [country.politicalSystem.legislature.lowerChamber]).map((chamber)=><li key={chamber.id}>{chamber.name}: {chamber.seats} escaños · {chamber.termYears} años · {(institutionLabels.elections as Record<string,string>)[chamber.electoralSystem]??'Regla electoral de la ficha del país'}</li>)}</ul><div className="source-list"><span className="eyebrow">FUENTES VERSIONADAS</span>{country.dataSources.map((source)=><a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.name} · {source.year} ↗</a>)}</div></section>}
      </>}
      </div></SceneDossier>}
      <footer>MANDATO <span>·</span> Ficción política y sátira; personajes y partidos generados <span>·</span> Guardado solo en este dispositivo <span>·</span> <div className="footer-links"><button onClick={() => setHallOpen(true)}>Salón de la fama</button><a href="/privacy.html">Privacidad</a><a href="/credits.html">Créditos y fuentes</a><a href="https://github.com/yohandry10/juego/issues" target="_blank" rel="noreferrer">Reportar un error ↗</a></div></footer>
    </section>{toolsOpen && <Drawer title="Opciones del juego" onClose={() => setToolsOpen(false)}><Switch label="Sonido y ambiente" checked={audio.enabled} onChange={audio.setEnabled}/><label>Volumen<input type="range" aria-label="Volumen" min="0" max="1" step="0.05" value={audio.volume} onChange={(event) => audio.setVolume(Number(event.target.value))}/></label><Switch label="Reducir movimiento" checked={reducedMotion} onChange={setReducedMotion}/><Button variant="quiet" onClick={() => { setTab("help"); setToolsOpen(false); }}>Ayuda y accesibilidad</Button><div className="game-tools">{state && <button onClick={() => exportCareer(state)}>Exportar partida</button>}{state?.ironman ? <span className="file-label">IRONMAN · guardado único</span> : <label className="file-label">Importar partida<input type="file" accept="application/json" onChange={(event) => { const file = event.target.files?.[0]; event.currentTarget.value = ""; if (file) void restoreImportedCareer(file); }}/></label>}{state && <button onClick={() => { if (state.ironman && !window.confirm("Nueva carrera reemplazará tu único guardado Ironman. ¿Continuar?")) return; setState(null); setPersonalizing(false); setTab("desk"); setWizardStep(1); setToolsOpen(false); setSeed(crypto.randomUUID()); }}>Nueva carrera</button>}</div><details><summary>Acerca de los datos</summary><p>País: {country.dataVersion}. Mundo: {state?.geopolitics.dataVersion ?? "mundo v1"}. Escenarios y personajes ficticios.</p></details><a href="/credits.html">Créditos y licencias</a></Drawer>}{hallOpen && <Suspense fallback={<p role="status">Cargando archivo local…</p>}><HallOfFame close={() => setHallOpen(false)}/></Suspense>}
  </main>{ceremony && <Ceremony transition={ceremony} close={() => { if (ceremony.after.stage === "election-result") { setCareerDetails(false); setTab("career"); } else { setTab("desk"); } setCeremony(null); }}/>}</>;
}

function stageLabel(state: CareerGameState) { return ({ campaign: "CAMPAÑA", "election-result": "ELECCIÓN", legislature: "LEGISLATURA", executive: "GOBIERNO", "party-leadership": "LIDERAZGO PARTIDARIO", minister: "MINISTERIO", "term-summary": "CIERRE", legacy: "LEGADO" })[state.stage]; }

function SceneDossier({open,close,children}:{open:boolean;close:()=>void;children:import("react").ReactNode}) { return open ? <Drawer title="Mi expediente de carrera" onClose={close}>{children}</Drawer> : <>{children}</>; }
